"use client";

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

export default function AppComponent() {
  const [theme, setTheme] = useState("light");
  const [count, setCount] = useState(0);
  const [showModal, setShowModal] = useState(false);
  const [items, setItems] = useState([]);
  const inputRef = useRef(null);
  const memoizedValue = useMemo(() => count * 2, [count]);
  const addItem = useCallback(() => {
  setItems(prev => [...prev, {
    id: Date.now(),
    text: `Item ${prev.length + 1}`
  }]);
}, []);
  const removeItem = useCallback(() => {
  setItems(prev => prev.slice(0, -1));
}, []);
  useEffect(() => {
    const interval = setInterval(() => setCount(c => c + 1), 3000);
  return () => clearInterval(interval);
  }, []);


  return (    <div
      style={{"width":"100%","height":"100%"}}
      data-component-id="root">
      <div
        className={`flex flex-col items-center justify-center min-h-screen p-6 transition-colors duration-500 ${theme === "dark" ? "bg-gray-900 text-white" : "bg-white text-gray-900"}`}
        data-component-id="element-1">
        <span
          data-component-id="element-1-expr-0">
          {/* Header */}
        </span>
        <undefined
          className="text-4xl font-bold mb-6"
          initial={{
  opacity: 0,
  y: -20
}}
          animate={{
  opacity: 1,
  y: 0
}}
          data-component-id="element-2">
          Complex React App
        </undefined>
        <span
          data-component-id="element-1-expr-2">
          {/* Theme Toggle */}
        </span>
        <button
          onClick={() => setTheme(theme === "light" ? "dark" : "light")}
          className="px-4 py-2 rounded-lg bg-indigo-500 text-white mb-4 shadow-md hover:bg-indigo-600"
          data-component-id="element-3">
          Toggle Theme
        </button>
        <span
          data-component-id="element-1-expr-4">
          {/* Counter */}
        </span>
        <undefined
          className="mb-6 text-2xl font-semibold"
          initial={{
  scale: 0
}}
          animate={{
  scale: 1
}}
          data-component-id="element-4">
          Count:{count}| Memoized:{memoizedValue}
        </undefined>
        <span
          data-component-id="element-1-expr-6">
          {/* Input Field */}
        </span>
        <div
          className="mb-4"
          data-component-id="element-5">
          <label
            className="block mb-1"
            data-component-id="element-6">
            Type Something:
          </label>
          <input
            ref={inputRef}
            className="border rounded-lg px-3 py-2 shadow-md text-gray-900"
            placeholder="Focus me!"
            data-component-id="element-7" />
        </div>
        <span
          data-component-id="element-1-expr-8">
          {/* Buttons */}
        </span>
        <div
          className="flex gap-4 mb-6"
          data-component-id="element-8">
          <button
            onClick={addItem}
            className="px-4 py-2 rounded-lg bg-green-500 text-white shadow-md hover:bg-green-600"
            data-component-id="element-9">
            Add Item
          </button>
          <button
            onClick={removeItem}
            className="px-4 py-2 rounded-lg bg-red-500 text-white shadow-md hover:bg-red-600"
            data-component-id="element-10">
            Remove Item
          </button>
          <button
            onClick={() => setShowModal(true)}
            className="px-4 py-2 rounded-lg bg-blue-500 text-white shadow-md hover:bg-blue-600"
            data-component-id="element-11">
            Show Modal
          </button>
        </div>
        <span
          data-component-id="element-1-expr-10">
          {/* Items List */}
        </span>
        <div
          className="grid grid-cols-2 gap-4 w-full max-w-md"
          data-component-id="element-12">
          <AnimatePresence
            data-component-id="element-13">
            {items.map((item, index) => (
              <undefined
                key={item.id}
                className="p-4 bg-indigo-100 rounded-lg shadow-md text-center font-medium text-gray-900"
                initial={{
  opacity: 0,
  scale: 0.8
}}
                animate={{
  opacity: 1,
  scale: 1
}}
                exit={{
  opacity: 0,
  scale: 0.8
}}
                data-component-id="element-14">
                {item.text}
              </undefined>
            ))}          </AnimatePresence>
        </div>
        <span
          data-component-id="element-1-expr-12">
          {/* Modal */}
        </span>
        <AnimatePresence
          data-component-id="element-15">
          {showModal && (
            <undefined
              className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50"
              initial={{
  opacity: 0
}}
              animate={{
  opacity: 1
}}
              exit={{
  opacity: 0
}}
              data-component-id="element-16" />
          )}        </AnimatePresence>
      </div>
    </div>
  );
}